def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or s.get('last_error_kind') in ('unknown_col', 'syntax'):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task') and not p.get('repeated_sql'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_handling'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    elif p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'ready_to_commit_candidate'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Identifier/schema issue: run DESCRIBE or SHOW COLUMNS for the target table, then use exact column names with backticks when they contain spaces, punctuation, or reserved words. Do not add a trailing dot to a column name.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the filtered columns, then relax one predicate or use LIKE/case-insensitive matching. Preserve exact punctuation, spaces, percent signs, and newlines in literals.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL is not adding evidence. Change strategy: inspect schema/sample values, simplify predicates, or cast text numerics before ranking, ordering, or aggregating.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numeric fields often need CAST for numeric comparison, ordering, ranking, or arithmetic. For final text answers, format numbers with requested separators or units while keeping database values exact.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. Use backticked identifiers and exact string literals; [] can be a normal successful mutation result.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: after a data-changing statement, SELECT the affected row(s) to confirm exact stored values. If the database state matches the request, commit a concise completion answer.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (p.get('mutation_not_attempted') or nb.get('stage') == 'mutation_needs_execution')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer list for a SELECT-style task; provide the SQL-derived values in the requested shape.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not (p.get('remaining_rounds_low') and nb.get('stage') == 'mutation_needs_execution'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task. Execute the INSERT, UPDATE, or DELETE first, then verify the affected rows before committing.'}
    return None
